  function diagramTitle(did) { for (var i = 0; i < DIAGRAMS.length; i++) if (DIAGRAMS[i][0] === did) return DIAGRAMS[i][1]; return DIAGRAM_DATA[did] ? DIAGRAM_DATA[did].title : nameOf(did); }
