    var itemOf = {};
    dg.items.forEach(function (it) { (getViewer() ? (getViewer().partsUnder[it.id] || [it.id]) : [it.id]).forEach(function (p) { itemOf[p] = it.id; }); index.byId[it.id].childIds.forEach(function () {}); });
    function itemFor(pid) {
      if (itemOf[pid]) return itemOf[pid];
      var path = index.byId[pid] ? index.byId[pid].path : [];
      for (var i = path.length - 1; i >= 0; i--) if (dg.items.some(function (it) { return it.id === path[i]; })) return path[i];
      return null;
    }
